// setupSerialStore opens a temp store + registry and creates one library bound
// to the seeded "serial" module. The marker facts the tests inject below
// simulate exactly what the serial-scanner plugin (group 2) will stamp per
// design.md §Interfaces §1/§2 — the drain logic keys ONLY on those fact names.
func setupSerialStore(t *testing.T) (*store.Store, *module.Registry, int64) {
	t.Helper()
	ctx := context.Background()
	s, err := store.Open(ctx, filepath.Join(t.TempDir(), "scan.db"))
	if err != nil {
		t.Fatalf("store.Open: %v", err)
	}
	t.Cleanup(func() { _ = s.Close() })
	r, err := module.Open(ctx, s)
	if err != nil {
		t.Fatalf("module.Open: %v", err)
	}
	libID, err := s.CreateLibrary(ctx, "serial", libRoot, "Serials")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	return s, r, libID
}

// mkSerialRecord builds an IdentifyResult whose parsed carries the
// serial-record marker facts (design.md §Interfaces §1) — the plugin-side
// stamp, simulated.
func mkSerialRecord(fileID, parsedJSON string) *scannerv1.IdentifyResult {
	r := &scannerv1.IdentifyResult{FileId: fileID, MediaType: "serial"}
	if err := json.Unmarshal([]byte(`{"parsed":`+parsedJSON+`,"media_type":"serial"}`), r); err != nil {
		panic(err)
	}
	return r
}

// serialLibrary is the fake serial-scanner emission: one directory-backed
// serial record ("Show") + two probed episode items whose parsed carries the
// §Interfaces §2 episode stamping.
func serialLibrary() *fakeScanner {
	return &fakeScanner{
		files: []*scannerv1.DiscoveredFile{
			mkFile("rec", "Show", nil, nil), // serial record: no ffprobe (D2 rule 1)
			mkFile("e1", "Show/E01.mkv", []byte(`{"format":{"duration":"120.5"}}`), nil),
			mkFile("e2", "Show/E02.mkv", []byte(`{"format":{"duration":"125.0"}}`), nil),
		},
		identify: map[string]*scannerv1.IdentifyResult{
			"rec": mkSerialRecord("rec", `{"serial_record":true,"dir_name_raw":"Show","backing":"directory","series_relative_path":"Show","series_sidecars":[]}`),
			"e1":  mkIdentified("e1", `{"title":"Show","season":1,"episode":1,"series_relative_path":"Show","sidecars":[{"relative_path":"Show/Eng/Show - 01.srt","kind":"subtitle","language":"Eng","match_basis":"sxxexx"}]}`),
			"e2":  mkIdentified("e2", `{"title":"Show","season":1,"episode":2,"series_relative_path":"Show","sidecars":[]}`),
		},
	}
}

// scanSerial runs one scan pass with the given fake over the serial library.
func scanSerial(t *testing.T, s *store.Store, r *module.Registry, libID int64, sc *fakeScanner) Result {
	t.Helper()
	rr := &recordingResolver{scanner: sc}
	res, err := runScan(context.Background(), s, r, rr.resolve, passthroughEnricher(), nil, libID)
	if err != nil {
		t.Fatalf("runScan: %v", err)
	}
	return res
}

// seriesRow fetches one series row by identity (test helper).
func seriesRow(t *testing.T, s *store.Store, libID int64, rel string) store.Series {
	t.Helper()
	sr, err := s.GetSeriesByPath(context.Background(), libID, rel)
	if err != nil {
		t.Fatalf("GetSeriesByPath(%q): %v", rel, err)
	}
	return sr
}

// seriesDerived is the derived-state fixture for the series carry tests
// (preserve-enrichment-rescan): the namespaces the enrich side stamps onto a
// settled series document besides the {parsed, ffprobe} base — sources.* per
// plugin plus the core-stamped provenance/view/stages trio. A series record is
// never packaged, so there is no `streams` lane here.
func seriesDerived() map[string]any {
	return map[string]any{
		"sources":     map[string]any{"serial-parser": map[string]any{"title": "Show"}},
		"_provenance": map[string]any{"serial-parser": "serial-parser@1.0.0"},
		"_view":       map[string]any{"poster": "/posters/show.jpg"},
		"_stages":     map[string]any{"identify": "done"},
	}
}

// stampSeriesDerived merges the derived-state fixture into a persisted series
// row's document and rewrites the row at the given status — the settled,
// enriched state the series carry tests rescan against.
func stampSeriesDerived(t *testing.T, ctx context.Context, s *store.Store, prior store.Series, derived map[string]any, status string) {
	t.Helper()
	var doc map[string]any
	if err := json.Unmarshal(prior.Document, &doc); err != nil {
		t.Fatalf("decode prior series document: %v", err)
	}
	for k, v := range derived {
		doc[k] = v
	}
	prior.Document = marshalDoc(doc)
	prior.Status = status
	if err := s.PutSeries(ctx, prior); err != nil {
		t.Fatalf("seed derived series: %v", err)
	}
}

// TestSeriesRescanIdempotent covers box 1.3: a serial record drains through the
// SAME loop as items into a series row (parsed marker facts + ffprobe {} for
// directory-backed), episodes keep their series_relative_path + sidecars
// stamping, and a second identical scan updates the series row IN PLACE — same
// id and created_at, stable count, no duplicate rows.
func TestSeriesRescanIdempotent(t *testing.T) {
	s, r, libID := setupSerialStore(t)
	ctx := context.Background()

	res := scanSerial(t, s, r, libID, serialLibrary())
	if res.Persisted != 3 { // 1 series record + 2 episodes
		t.Fatalf("Persisted = %d, want 3 (series record + 2 episodes)", res.Persisted)
	}

	prior := seriesRow(t, s, libID, "Show")
	if prior.ID == "" || prior.Status != "pending" {
		t.Fatalf("series row = %+v, want a pending row with a minted id", prior)
	}
	var doc struct {
		Parsed  map[string]any `json:"parsed"`
		Ffprobe map[string]any `json:"ffprobe"`
	}
	if err := json.Unmarshal(prior.Document, &doc); err != nil {
		t.Fatalf("decode series document: %v", err)
	}
	if doc.Parsed["serial_record"] != true || doc.Parsed["dir_name_raw"] != "Show" {
		t.Errorf("series parsed = %v, want the serial-record marker facts", doc.Parsed)
	}
	if doc.Ffprobe == nil || len(doc.Ffprobe) != 0 {
		t.Errorf("series ffprobe = %v, want {} for a directory-backed record (Interfaces §4)", doc.Ffprobe)
	}

	// Episode items carry the §2 stamping verbatim.
	items, err := s.QueryItems(ctx, libID, "", 100, 0)
	if err != nil {
		t.Fatalf("QueryItems: %v", err)
	}
	if len(items) != 2 {
		t.Fatalf("items = %d, want 2 (the serial record is never an item)", len(items))
	}
	for _, it := range items {
		var d scannedDoc
		if err := json.Unmarshal(it.Document, &d); err != nil {
			t.Fatalf("decode item doc: %v", err)
		}
		if d.Parsed["series_relative_path"] != "Show" {
			t.Errorf("item %q series_relative_path = %v, want Show", it.FileID, d.Parsed["series_relative_path"])
		}
	}
	e1 := items[0]
	if e1.FileID != "e1" {
		e1 = items[1]
	}
	var e1doc struct {
		Parsed struct {
			Sidecars []map[string]any `json:"sidecars"`
		} `json:"parsed"`
	}
	if err := json.Unmarshal(e1.Document, &e1doc); err != nil {
		t.Fatalf("decode e1 doc: %v", err)
	}
	if len(e1doc.Parsed.Sidecars) != 1 || e1doc.Parsed.Sidecars[0]["match_basis"] != "sxxexx" {
		t.Errorf("e1 sidecars = %v, want one sxxexx-matched subtitle", e1doc.Parsed.Sidecars)
	}

	// Re-scan the unchanged library: the series row updates in place.
	time.Sleep(2 * time.Millisecond)
	scanSerial(t, s, r, libID, serialLibrary())

	after := seriesRow(t, s, libID, "Show")
	if after.ID != prior.ID {
		t.Errorf("series ID = %q, want %q (in-place upsert)", after.ID, prior.ID)
	}
	if !after.CreatedAt.Equal(prior.CreatedAt) {
		t.Errorf("CreatedAt = %v, want %v (preserved on re-scan)", after.CreatedAt, prior.CreatedAt)
	}
	ids, err := s.ListSeriesIDs(ctx, libID)
	if err != nil {
		t.Fatalf("ListSeriesIDs: %v", err)
	}
	if len(ids) != 1 {
		t.Fatalf("series count = %d, want 1 (no duplicate rows across re-scans)", len(ids))
	}
	if after.Status != "pending" {
		t.Errorf("Status = %q, want pending (unchanged facts preserve prior status)", after.Status)
	}
}

// TestSeriesUnchangedRescanPreservesReady covers box 1.4 + the series tier-A
// carry (preserve-enrichment-rescan): first sight lands "pending"; an
// unchanged re-scan preserves the prior status (a ready series is NOT
// regressed) AND carries the prior document's derived namespaces verbatim
// beside the fresh base; changed serial facts advance to "stale" and drop
// every derived namespace.
func TestSeriesUnchangedRescanPreservesReady(t *testing.T) {
	record := func(dirName string) *fakeScanner {
		sc := serialLibrary()
		sc.identify["rec"] = mkSerialRecord("rec",
			`{"serial_record":true,"dir_name_raw":"`+dirName+`","backing":"directory","series_relative_path":"Show","series_sidecars":[]}`)
		return sc
	}

	cases := []struct {
		name       string
		rescan     *fakeScanner
		wantStatus string
	}{
		{
			name:       "first_sight_pending",
			rescan:     nil,
			wantStatus: "pending",
		},
		{
			name:       "unchanged_rescan_preserves_ready",
			rescan:     record("Show"), // identical facts
			wantStatus: "ready",
		},
		{
			name:       "changed_facts_to_stale",
			rescan:     record("Show.2022.REPACK"), // dir_name_raw changed
			wantStatus: "stale",
		},
	}
	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			s, r, libID := setupSerialStore(t)
			ctx := context.Background()

			scanSerial(t, s, r, libID, serialLibrary())
			if tc.name == "first_sight_pending" {
				if got := seriesRow(t, s, libID, "Show").Status; got != "pending" {
					t.Fatalf("first-sight status = %q, want pending", got)
				}
				return
			}

			// Promote the series to ready with an ENRICHED document — the same
			// document scan #1 wrote plus the derived namespaces the enrich
			// side stamps onto a settled series — then re-scan.
			prior := seriesRow(t, s, libID, "Show")
			stampSeriesDerived(t, ctx, s, prior, seriesDerived(), "ready")
			scanSerial(t, s, r, libID, tc.rescan)

			after := seriesRow(t, s, libID, "Show")
			if after.Status != tc.wantStatus {
				t.Fatalf("re-scan status = %q, want %q", after.Status, tc.wantStatus)
			}
			var doc map[string]any
			if err := json.Unmarshal(after.Document, &doc); err != nil {
				t.Fatalf("decode re-scanned document: %v", err)
			}
			if tc.name == "changed_facts_to_stale" {
				// Stale leg: the changed parsed identity invalidates every
				// derived namespace — the fresh base alone survives.
				for k := range seriesDerived() {
					if _, ok := doc[k]; ok {
						t.Errorf("derived namespace %q survived a parsed change, want dropped", k)
					}
				}
				return
			}
			// Unchanged leg: the derived namespaces survive verbatim beside the
			// fresh base (the upsert replaces the document; scan carried them).
			for k, want := range seriesDerived() {
				got, ok := doc[k]
				if !ok {
					t.Errorf("derived namespace %q missing after rescan (doc=%s)", k, canonicalJSON(doc))
					continue
				}
				if !canonicalEqual(got, want) {
					t.Errorf("carried %q = %s, want %s (verbatim carry)", k, canonicalJSON(got), canonicalJSON(want))
				}
			}
			if parsed, _ := doc["parsed"].(map[string]any); parsed["dir_name_raw"] != "Show" {
				t.Errorf("rescanned parsed.dir_name_raw = %v, want the fresh base's facts", parsed["dir_name_raw"])
			}
		})
	}
}

// TestSeriesFfprobeDriftPreservesDerived is the series tier-B leg
// (preserve-enrichment-rescan) over a FILE-BACKED series record — the only
// shape where the ffprobe base can drift at all: a directory-backed record's
// base carries an empty ffprobe {} (Interfaces §4), so a re-scan of the same
// directory compares byte-equal on ffprobe and tier B is a no-op there. Here
// the re-scan carries the SAME parsed facts but a DIFFERENT FfprobeJson
// (scanner toolchain drift): the status is preserved, the derived namespaces
// survive verbatim, and the ffprobe blob refreshes to the new value (the fresh
// base wins for the reserved keys). A series record is never packaged, so —
// unlike the item tier B — `streams` has no lane here and nothing is dropped:
// derivedCarry runs with dropStreams=false in both tiers.
func TestSeriesFfprobeDriftPreservesDerived(t *testing.T) {
	probeA := []byte(`{"format":{"duration":"120.5"}}`)
	probeB := []byte(`{"format":{"duration":"120.6","bit_rate":"8000000"}}`)
	record := func(probe []byte) *fakeScanner {
		sc := serialLibrary()
		sc.files[0] = mkFile("rec", "Show", probe, nil) // file-backed: the record itself is probed
		sc.identify["rec"] = mkSerialRecord("rec",
			`{"serial_record":true,"dir_name_raw":"Show","backing":"file","series_relative_path":"Show","series_sidecars":[]}`)
		return sc
	}
	derived := seriesDerived()

	s, r, libID := setupSerialStore(t)
	ctx := context.Background()

	scanSerial(t, s, r, libID, record(probeA))
	prior := seriesRow(t, s, libID, "Show")
	stampSeriesDerived(t, ctx, s, prior, derived, "ready")
	scanSerial(t, s, r, libID, record(probeB))

	after := seriesRow(t, s, libID, "Show")
	if after.Status != "ready" {
		t.Errorf("ffprobe-drift re-scan status = %q, want ready (tier B preserves the prior status)", after.Status)
	}
	var doc map[string]any
	if err := json.Unmarshal(after.Document, &doc); err != nil {
		t.Fatalf("decode re-scanned document: %v", err)
	}
	for k, want := range derived {
		got, ok := doc[k]
		if !ok {
			t.Errorf("derived namespace %q missing after ffprobe drift (doc=%s)", k, canonicalJSON(doc))
			continue
		}
		if !canonicalEqual(got, want) {
			t.Errorf("carried %q = %s, want %s (verbatim carry)", k, canonicalJSON(got), canonicalJSON(want))
		}
	}
	var wantProbe map[string]any
	if err := json.Unmarshal(probeB, &wantProbe); err != nil {
		t.Fatalf("decode probeB: %v", err)
	}
	if !canonicalEqual(doc["ffprobe"], wantProbe) {
		t.Errorf("ffprobe = %s, want refreshed to %s", canonicalJSON(doc["ffprobe"]), probeB)
	}
}

// TestSeriesRenameNewIdentity covers box 1.5: after a CLEAN drain of a library
// whose directory was renamed, the new path is a NEW ser_ identity landing
// "pending" with a fresh document (no metadata copied across identities), and
// the old row is swept to "deleted".
func TestSeriesRenameNewIdentity(t *testing.T) {
	s, r, libID := setupSerialStore(t)

	scanSerial(t, s, r, libID, serialLibrary())
	old := seriesRow(t, s, libID, "Show")

	// The directory was renamed on disk: the next pass emits the new identity
	// only (and no longer re-observes "Show"). The pass opts in to a confirmed
	// clean end (D4) — the old-row-tombstoned assertion needs the sweep, which
	// runs only on a confirmed clean drain.
	renamed := serialLibrary()
	renamed.endClean = true
	renamed.files[0] = mkFile("rec2", "Show Renamed", nil, nil)
	renamed.identify["rec2"] = mkSerialRecord("rec2",
		`{"serial_record":true,"dir_name_raw":"Show Renamed","backing":"directory","series_relative_path":"Show Renamed","series_sidecars":[]}`)
	for _, ep := range []string{"e1", "e2"} {
		var ir struct {
			Parsed map[string]any `json:"parsed"`
		}
		b, _ := json.Marshal(renamed.identify[ep])
		if err := json.Unmarshal(b, &ir); err != nil {
			t.Fatalf("decode episode identify: %v", err)
		}
		ir.Parsed["series_relative_path"] = "Show Renamed"
		nb, _ := json.Marshal(ir)
		var out scannerv1.IdentifyResult
		if err := json.Unmarshal(nb, &out); err != nil {
			t.Fatalf("rebuild episode identify: %v", err)
		}
		renamed.identify[ep] = &out
	}

	time.Sleep(2 * time.Millisecond)
	scanSerial(t, s, r, libID, renamed)

	fresh := seriesRow(t, s, libID, "Show Renamed")
	if fresh.Status != "pending" {
		t.Errorf("new identity status = %q, want pending (enrichment re-derives from scratch)", fresh.Status)
	}
	if fresh.ID == old.ID {
		t.Errorf("renamed directory reused the old id %q — identity must be (library_id, relative_path)", fresh.ID)
	}
	var freshDoc map[string]any
	if err := json.Unmarshal(fresh.Document, &freshDoc); err != nil {
		t.Fatalf("decode new document: %v", err)
	}
	if parsed, _ := freshDoc["parsed"].(map[string]any); parsed["dir_name_raw"] != "Show Renamed" {
		t.Errorf("new document parsed.dir_name_raw = %v, want the NEW directory name", parsed["dir_name_raw"])
	}
	for _, key := range []string{"sources", "_provenance", "_view", "_stages"} {
		if _, ok := freshDoc[key]; ok {
			t.Errorf("new document carries %q — no metadata may be copied across identities", key)
		}
	}

	swept := seriesRow(t, s, libID, "Show")
	if swept.Status != "deleted" {
		t.Errorf("old identity status = %q, want deleted (post-drain sweep)", swept.Status)
	}
}

// TestSeriesReobservedDeletedSelfHeals covers fix-truncated-scan-sweep 2.2
// (D3): on a CONFIRMED clean pass, a "deleted" series row that the pass
// re-observes with unchanged facts self-heals to "ready" (lifting the
// tombstones a historical truncated pass wrote), changed facts still land
// "stale" (the baseChanged rule fires first), and a "deleted" row the clean
// pass never re-observes (the Ghost.Show shape) keeps "deleted" — the sweep's
// existing skip, with no updated_at churn.
func TestSeriesReobservedDeletedSelfHeals(t *testing.T) {
	s, r, libID := setupSerialStore(t)
	ctx := context.Background()

	// endClean fakes throughout: the heal is a clean-pass behavior (D4).
	clean := func() *fakeScanner {
		sc := serialLibrary()
		sc.endClean = true
		return sc
	}

	scanSerial(t, s, r, libID, clean())
	// (a) Force the wrongful tombstone, keeping the same document the scan
	// wrote — the 2026-10-12 incident shape (status column flipped only).
	show := seriesRow(t, s, libID, "Show")
	show.Status = "deleted"
	if err := s.PutSeries(ctx, show); err != nil {
		t.Fatalf("tombstone Show: %v", err)
	}
	// (c) seed: a second deleted row the pass never re-observes (Ghost.Show).
	ghost := store.Series{
		ModuleID: "serial", LibraryID: libID, RelativePath: "Ghost.Show",
		Document:      json.RawMessage(`{"parsed":{"serial_record":true},"ffprobe":{}}`),
		SchemaVersion: 1, Status: "deleted",
	}
	if err := s.PutSeries(ctx, ghost); err != nil {
		t.Fatalf("seed Ghost.Show: %v", err)
	}

	// (a) An unchanged clean re-scan re-observes Show → the tombstone lifts.
	scanSerial(t, s, r, libID, clean())
	if got := seriesRow(t, s, libID, "Show").Status; got != "ready" {
		t.Errorf("re-observed deleted series status = %q, want ready (self-heal)", got)
	}

	// (b) A re-scan with changed serial facts lands "stale" — the baseChanged
	// rule fires BEFORE the heal (a stale row must not mask a changed base).
	changed := clean()
	changed.identify["rec"] = mkSerialRecord("rec",
		`{"serial_record":true,"dir_name_raw":"Show.2022.REPACK","backing":"directory","series_relative_path":"Show","series_sidecars":[]}`)
	scanSerial(t, s, r, libID, changed)
	if got := seriesRow(t, s, libID, "Show").Status; got != "stale" {
		t.Errorf("changed-facts re-scan status = %q, want stale (baseChanged fires first)", got)
	}

	// (c) The un-re-observed deleted row keeps "deleted" after both clean
	// passes — no wrongful resurrection, no updated_at churn.
	if got := seriesRow(t, s, libID, "Ghost.Show").Status; got != "deleted" {
		t.Errorf("un-re-observed deleted series status = %q, want deleted (sweep skip)", got)
	}
}

// TestCancelledScanDoesNotSweep covers box 1.6: a scan whose stream did not
// drain cleanly (cancelled context) performs NO sweep — no series row, not even
// one the partial pass never observed, reaches "deleted".
func TestCancelledScanDoesNotSweep(t *testing.T) {
	s, r, libID := setupSerialStore(t)
	ctx := context.Background()

	// Prior state: two settled (ready) series — "Show" (about to be re-observed
	// by the partial pass) and "Ghost.Show" (never observed at all).
	scanSerial(t, s, r, libID, serialLibrary())
	show := seriesRow(t, s, libID, "Show")
	show.Status = "ready"
	if err := s.PutSeries(ctx, show); err != nil {
		t.Fatalf("promote Show: %v", err)
	}
	ghost := store.Series{
		ModuleID: "serial", LibraryID: libID, RelativePath: "Ghost.Show",
		Document:      json.RawMessage(`{"parsed":{"serial_record":true},"ffprobe":{}}`),
		SchemaVersion: 1, Status: "ready",
	}
	if err := s.PutSeries(ctx, ghost); err != nil {
		t.Fatalf("seed Ghost.Show: %v", err)
	}

	// A cancelled re-scan: emit the Show record, then block mid-stream until
	// the consumer cancels.
	scanCtx, cancel := context.WithCancel(context.Background())
	defer cancel()
	sc := serialLibrary()
	sc.blockAfter = 1
	rr := &recordingResolver{scanner: sc}

	done := make(chan error, 1)
	go func() {
		_, err := runScan(scanCtx, s, r, rr.resolve, passthroughEnricher(), nil, libID)
		done <- err
	}()
	deadline := time.Now().Add(3 * time.Second)
	for time.Now().Before(deadline) {
		if _, err := s.GetSeriesByPath(context.Background(), libID, "Show"); err == nil {
			break // the partial pass re-persisted Show
		}
		time.Sleep(2 * time.Millisecond)
	}
	cancel()

	select {
	case err := <-done:
		if err == nil {
			t.Fatal("runScan: want context error on cancelled drain, got nil")
		}
	case <-time.After(3 * time.Second):
		t.Fatal("runScan did not return after cancel (goroutine leak?)")
	}

	for _, tc := range []struct {
		rel string
	}{
		{"Show"}, {"Ghost.Show"},
	} {
		sr := seriesRow(t, s, libID, tc.rel)
		if sr.Status == "deleted" {
			t.Errorf("series %q reached deleted on a cancelled scan — the sweep must not run on a partial pass", tc.rel)
		}
		if sr.Status != "ready" {
			t.Errorf("series %q status = %q, want ready (untouched by the partial pass)", tc.rel, sr.Status)
		}
	}
}
